[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$RollbackDirectory)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
try{$rollback=[IO.Path]::GetFullPath($RollbackDirectory);$plan=Get-Content (Join-Path $rollback "transaction-plan.json") -Raw|ConvertFrom-Json;if($plan.schemaVersion-ne1-or$plan.purpose-cne"hase-minipc-python-provisioning-transaction"){throw"plan"};if(@(Get-Process Hase.DesktopHost.App,Hase.Client.Wpf.App -ErrorAction SilentlyContinue).Count-ne0){throw"processes"};$entries=@($plan.entries);$root=[string]($entries|? name -eq"provisioningDirectory").path;$cert=[string]($entries|? name -eq"certificate").path;$key=[string]($entries|? name -eq"privateKey").path;$profile=[string]($entries|? name -eq"pythonProfile").path;$enrollment=[string]($entries|? name -eq"enrollment").path;$policy=[string]($entries|? name -eq"authorizationPolicy").path;$app=[string]($entries|? name -eq"applicationProfile").path;$tool=Split-Path -Parent $MyInvocation.MyCommand.Path;$pkg=Split-Path -Parent $tool;$repo=[IO.Path]::GetFullPath((Split-Path -Parent(Split-Path -Parent $pkg)));$operator=Join-Path $repo "src\Hase.Python.CredentialProvisioning.Operator"
 if(Test-Path $root -PathType Container){$journals=@(Get-ChildItem $root -Filter ".hase-python-provisioning-*.journal.json*" -File);if($journals.Count-gt0){&dotnet run --project $operator -c Release -- recover --provisioning-directory $root --certificate $cert --private-key $key --profile $profile --enrollment $enrollment --authorization-policy $policy 1>$null 2>$null;if($LASTEXITCODE-ne0){throw"operator-recovery"}}}
 Copy-Item (Join-Path $rollback "enrollment.original") ($enrollment+".restore") -Force;[IO.File]::Replace($enrollment+".restore",$enrollment,$null);Copy-Item (Join-Path $rollback "application-profile.original") ($app+".restore") -Force;[IO.File]::Replace($app+".restore",$app,$null)
 foreach($f in @($cert,$key,$profile,$policy)){if(Test-Path $f){Remove-Item $f -Force}};if(Test-Path $root){if(@(Get-ChildItem $root -Force).Count-ne0){throw"custody-not-empty"};Remove-Item $root -Force};$journal=Join-Path $rollback "publication-journal.json";if(Test-Path $journal){Remove-Item $journal -Force}
 Write-Host "Enrollment restored          : True";Write-Host "Application profile restored : True";Write-Host "Python outputs absent        : True";Write-Host "Authorization policy absent  : True";Write-Host "Private custody absent       : True";Write-Host "Publication recovery complete: True"}catch{Write-Error "MiniPC Python credential publication recovery failed.";exit 1}
